// tenant_feature_gate.ts
export function requireAuditExportBeta(req: Request): void {
  const tenantId = req.auth.tenant_id;
  const decision = featureFlags.evaluateTenantFlag(
    'siem_audit_export_beta',
    tenantId,
    { env: req.env.name }
  );

  metrics.featureFlagDecisionTotal.inc({
    flag: 'siem_audit_export_beta',
    result: decision.enabled ? 'enabled' : 'disabled',
    reason: decision.reason,
  });

  if (!decision.enabled) {
    // 404 to avoid exposing feature existence / eligibility rules.
    throw httpErrors.notFound('resource not found');
  }
}
